class ArgumentParser: 
    def __init__(self):
        """
        Initialize the fields.
        self.arguments is a dict that stores the args in a command line
        self.requried is a set that stores the required arguments
        self.types is a dict that stores type of every arguments.
        >>> parser.arguments
        {'key1': 'value1', 'option1': True}
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'type1'}
        """
        self.arguments = {}
        self.required = set()
        self.types = {}

    def parse_arguments(self, command_string):
        self.arguments.clear()
        missing_args = set()

        parts = command_string.split()

        if len(parts) < 2:
            return (False, set())

        # Skip first 2 tokens (python executable and script name)
        i = 2

        while i < len(parts):
            token = parts[i]

            if token.startswith('--'):
                arg_name = token[2:]
                if '=' in token:  # --arg=value
                    arg = arg_name
                    value = token.split('=', 1)[1]
                    self.arguments[arg] = self._convert_type(arg, value)
                    i += 1
                elif (i + 1) < len(parts):
                    # --arg value (space-separated)
                    arg = arg_name
                    value = parts[i + 1]
                    self.arguments[arg] = self._convert_type(arg, value)
                    i += 2
                else:
                    # --arg (boolean flag)
                    arg = arg_name
                    self.arguments[arg] = True
                    i += 1
            elif token.startswith('-') and not token.startswith('--'):
                # -flag (single dash, possibly multi-char)
                arg = token[1:]
                if '=' in token:  # -arg=value
                    value = token.split('=', 1)[1]
                    self.arguments[arg] = self._convert_type(arg, value)
                    i += 1
                elif (i + 1) < len(parts):
                    # -arg value (space-separated)
                    value = parts[i + 1]
                    self.arguments[arg] = self._convert_type(arg, value)
                    i += 2
                else:
                    # -arg (boolean flag)
                    self.arguments[arg] = True
                    i += 1
            else:
                # Positional argument
                arg = token
                self.arguments[arg] = self._convert_type(arg, token)
                i += 1

        # Check for missing required arguments
        for arg in self.required:
            if arg not in self.arguments:
                missing_args.add(arg)

        if missing_args:
            return (False, missing_args)

        return (True, None)

    def get_argument(self, key):
        if key in self.arguments:
            return self.arguments[key]
        return None

    def add_argument(self, arg, required=False, arg_type=str):
        self.types[arg] = arg_type
        if required:
            self.required.add(arg)

    def _convert_type(self, arg, value):
        if arg in self.types:
            type_name = self.types[arg]
            if type_name == 'int':
                try:
                    return int(value)
                except ValueError:
                    return value
            elif type_name == 'float':
                try:
                    return float(value)
                except ValueError:
                    return value
            elif type_name == 'bool':
                try:
                    if value.lower() in ('true', '1', 'yes', 'on'):
                        return True
                    elif value.lower() in ('false', '0', 'no', 'off'):
                        return False
                    else:
                        return value
                except:
                    return value
            else:
                # For any other type string, assume str
                return value
        return value
